const e = $input.first().json;
const wf = String((e.workflow && e.workflow.name) || '');
const ex = e.execution || {};
const MAPA = [['CA_8.1_', 'A01'], ['CA_8.2_', 'A02'], ['CA_8.3_', 'A03'], ['CA_8.4a_', 'A04'], ['CA_8.4b_', 'A05'], ['CA_8.4c_', 'A06'], ['CA_8.4d_', 'A07'], ['CA_8.4_Orquestador', 'A04'], ['CA_8.5a_', 'A08'], ['CA_8.5b_', 'A09'], ['CA_8.5c_', 'A10'], ['CA_8.5_Orquestador', 'A08'], ['CA_8.6', 'A11'], ['CA_8.7', 'A12'], ['CA_8.8a_', 'A14'], ['CA_8.8b_', 'A13'], ['CA_8.8c_', 'A13'], ['CA_9_PRUEBA', 'A08']];
const par = MAPA.find(([p]) => wf.startsWith(p));
if (!par) return [];
const msg = String((ex.error && ex.error.message) || 'error sin mensaje').split('\n')[0];
const detalle = ((ex.lastNodeExecuted || 'nodo desconocido') + ': ' + msg).slice(0, 300);
const doc = wf.includes('PRUEBA') ? 'PRUEBA-ERR-' + String(ex.id || '') : '';
return [{ json: { automatizacion_id: par[1], documento_id: doc, detalle } }];
